const D = { energy:.62, density:.6, speed:1, span:.5, scale:1, hue:210, x:.5, y:.5, style:'survey', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const style = P.style, sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const TAU = Math.PI * 2;
const smooth = t => t < 0 ? 0 : t > 1 ? 1 : t * t * (3 - 2 * t);

// ---- seed-deterministic galaxy catalog with walls / fingers-of-god / voids ----
const NG = Math.round(1100 + P.density * 3400);
if (!S.gal || S.galSeed !== sd || S.galN !== NG) {
  S.galSeed = sd; S.galN = NG;
  const NC = 10, NW = 5;                                   // clusters (fingers) + walls
  const raC = [], dC = [], dW = [], wRa0 = [], wRa1 = [];
  for (let k = 0; k < NC; k++) { raC.push(fr(k*3+1)); dC.push(0.18 + fr(k*3+2) * 0.7); }
  for (let k = 0; k < NW; k++) { dW.push(0.12 + fr(k*4+40) * 0.8); wRa0.push(fr(k*4+41)); wRa1.push(fr(k*4+41) + 0.25 + fr(k*4+42) * 0.5); }
  const cone = new Uint8Array(NG), ra = new Float32Array(NG), d0 = new Float32Array(NG);
  const sz = new Float32Array(NG), tw = new Float32Array(NG);
  for (let i = 0; i < NG; i++) {
    cone[i] = fr(i * 7 + 3) < 0.5 ? 0 : 1;
    const typ = fr(i * 7 + 4);
    if (typ < 0.34) {                                       // finger-of-god cluster member
      const c = (fr(i * 7 + 5) * NC) | 0;
      ra[i] = raC[c] + (fr(i * 7 + 6) - 0.5) * 0.018;       // tight in RA
      d0[i] = dC[c] + (fr(i * 7 + 8) - 0.5) * 0.075;        // spread radially -> finger
    } else if (typ < 0.62) {                                // wall member
      const w = (fr(i * 7 + 9) * NW) | 0;
      d0[i] = dW[w] + (fr(i * 7 + 10) - 0.5) * 0.03;
      ra[i] = wRa0[w] + fr(i * 7 + 11) * (wRa1[w] - wRa0[w]);
    } else {                                                // field galaxy (voids emerge as gaps)
      ra[i] = fr(i * 7 + 12);
      let dd = fr(i * 7 + 13);
      // carve a couple of voids by pushing field galaxies out of empty bands
      if (dd > 0.30 && dd < 0.44) dd = 0.30 - (dd - 0.30);
      if (dd > 0.60 && dd < 0.72) dd = 0.72 + (dd - 0.60);
      d0[i] = Math.max(0.02, Math.min(0.98, dd));
    }
    ra[i] = ((ra[i] % 1) + 1) % 1;
    sz[i] = 0.5 + fr(i * 7 + 14) * fr(i * 7 + 14) * 2.2;
    tw[i] = fr(i * 7 + 15) * TAU;
  }
  S.gal = { cone, ra, d0, sz, tw };
}
const G = S.gal;

const T = K.t * (0.4 + P.speed * 0.6);
const cx = P.x * width, cy = P.y * height;
const Rmax = 0.72 * Math.max(width, height) * (0.7 + P.scale * 0.5);
const halfOpen = (25 + P.span * 55) * Math.PI / 180;      // half opening angle 25..80 deg
const flow = 0.045 * (0.4 + P.speed);                     // Hubble-flow scroll rate
const expo = 0.5 + P.energy * 1.1;
const gain = 1 + K.swell * 0.12 + A.rms * 0.2;

// redshift color ramp: near(blue) -> green -> far(red)
function zcol(z, out) {
  let r, g, b;
  if (style === 'cfa') { r = 250; g = 180 - z * 40; b = 70; }              // amber plotter
  else if (style === 'blueprint') { r = 40 + z * 30; g = 150 + z * 40; b = 255 - z * 40; } // cyan schematic
  else if (style === 'heat') { r = 120 + z * 135; g = 40 + (1 - Math.abs(z - 0.5) * 2) * 150; b = 30 + (1 - z) * 90; }
  else { // survey blue->green->red
    if (z < 0.5) { const s = z * 2; r = 40 + s * 40; g = 120 + s * 130; b = 255 - s * 150; }
    else { const s = (z - 0.5) * 2; r = 80 + s * 175; g = 250 - s * 200; b = 105 - s * 85; }
  }
  out[0] = r; out[1] = g; out[2] = b;
}
const col = [0, 0, 0];

// full-frame clear (deep-space ground; prevents ADD-trail accumulation outside the wedge)
background(style === 'blueprint' ? 215 : 235, style === 'cfa' ? 30 : 45, 5);

// ---- dim wedge sector fill (luminance floor + reads as the surveyed volume) ----
push();
noStroke();
const sectorFill = () => {
  for (let cn = 0; cn < 2; cn++) {
    const base = cn === 0 ? -Math.PI / 2 : Math.PI / 2;
    const gc = style === 'blueprint' ? [8, 22, 40] : style === 'cfa' ? [24, 18, 8] : [10, 14, 26];
    for (let ring = 3; ring >= 1; ring--) {
      const rr = Rmax * ring / 3;
      fill(gc[0], gc[1], gc[2], 26);
      beginShape();
      vertex(cx, cy);
      for (let a = -halfOpen; a <= halfOpen; a += halfOpen / 12) vertex(cx + Math.cos(base + a) * rr, cy + Math.sin(base + a) * rr);
      endShape(CLOSE);
    }
  }
};
sectorFill();
pop();

// ---- faint survey grid (arcs + spokes) ----
push();
noFill();
const gridA = style === 'blueprint' ? 22 : 9;
stroke(style === 'blueprint' ? 190 : 0, style === 'blueprint' ? 40 : 0, 100, gridA * (P.alpha / 100));
strokeWeight(Math.max(1, u * 0.0011));
for (let cn = 0; cn < 2; cn++) {
  const base = cn === 0 ? -Math.PI / 2 : Math.PI / 2;
  for (let ring = 1; ring <= 4; ring++) {
    const rr = Rmax * ring / 4;
    beginShape();
    for (let a = -halfOpen; a <= halfOpen; a += halfOpen / 16) vertex(cx + Math.cos(base + a) * rr, cy + Math.sin(base + a) * rr);
    endShape();
  }
  for (let sp = -2; sp <= 2; sp++) {
    const a = base + (sp / 2) * halfOpen;
    line(cx, cy, cx + Math.cos(a) * Rmax, cy + Math.sin(a) * Rmax);
  }
}
pop();

// ---- galaxies (Hubble flow outward) ----
push();
blendMode(ADD);
noStroke();
const cone = G.cone, gra = G.ra, gd0 = G.d0, gsz = G.sz, gtw = G.tw;
for (let i = 0; i < NG; i++) {
  let d = (gd0[i] + flow * T) % 1;
  if (d < 0) d += 1;
  const fade = smooth(d / 0.06) * smooth((1 - d) / 0.10);  // fade in at apex, out at far edge
  if (fade <= 0.01) continue;
  const base = cone[i] === 0 ? -Math.PI / 2 : Math.PI / 2;
  const a = base + (gra[i] - 0.5) * 2 * halfOpen;
  const r = d * Rmax;
  const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r;
  zcol(d, col);
  const twk = 0.72 + 0.28 * Math.sin(T * (0.5 + gsz[i] * 0.3) + gtw[i]) + K.pulse * 0.12 + A.treble * 0.3;
  const b = (28 + P.energy * 60) * fade * twk * (P.alpha / 100);
  const sz = gsz[i] * (u * 0.0016) * (0.8 + P.scale * 0.5) * (0.7 + P.energy * 0.5);
  // p5 fill is HSB; convert rgb->approx by drawing via RGB using colorMode-independent trick: use fill with rgb through 'color'? use tint? -> use fill in HSB not possible directly; emulate by fill(r,g,b) won't work in HSB. Use drawingContext.
  drawingContext.globalAlpha = Math.min(0.85, b / 100);
  drawingContext.fillStyle = `rgb(${col[0] | 0},${col[1] | 0},${col[2] | 0})`;
  drawingContext.beginPath();
  drawingContext.arc(x, y, Math.max(0.6, sz), 0, TAU);
  drawingContext.fill();
}
drawingContext.globalAlpha = 1;
// observer glint at apex
blendMode(BLEND);
pop();
